// REGEX CONSTRUCTION: NFA/DFA Compilation (Runtime Cost)
// Pattern parsing and state machine generation happens here.
std::regex compiled_pattern("([A-Z]+)(\\d+)"); 

std::string sequence = "START123_END";
std::smatch match_results;

// REGEX_SEARCH: NFA/DFA Traversal
// Sequence is fed to the state machine defined by compiled_pattern.
bool success = std::regex_search(sequence.cbegin(), 
                                 sequence.cend(), 
                                 match_results, 
                                 compiled_pattern);

// match_results[0] is the full matched substring
// match_results[1] holds the first capture group
// Backtracking cost depends on NFA structure and input size.
